defmodule Lmx.ReleaseSigningTest do
  # Every key here is generated by the test and lives in a directory made for
  # it; the real release key is never involved, and the repository's pinned
  # files are only read. Task output goes through Mix.shell(), which
  # capture_io captures for this process alone.
  use ExUnit.Case, async: true

  import ExUnit.CaptureIO

  alias Lmx.Update.Signature
  alias Lmx.Update.Signing
  alias Mix.Tasks.Lmx.Release

  @repo Path.expand("../../../..", __DIR__)

  # Not ExUnit's tmp_dir: that sits inside this checkout, where the tasks
  # refuse to write or read a private key.
  setup do
    tmp =
      Path.join(System.tmp_dir!(), "lmx-signing-" <> Base.encode16(:crypto.strong_rand_bytes(6)))

    File.mkdir_p!(tmp)
    on_exit(fn -> File.rm_rf!(tmp) end)

    assert :ok = Signing.outside_checkout(Path.join(tmp, "probe.key")),
           "TMPDIR is inside a checkout"

    %{tmp: tmp}
  end

  # A copy of the layout the tasks write to: dist/lmx/release-signing.pub and
  # scripts/install.py, two levels up.
  defp layout(tmp) do
    root = Path.join(tmp, "dist/lmx")
    File.mkdir_p!(root)
    File.mkdir_p!(Path.join(tmp, "scripts"))
    File.write!(Path.join(root, "release-signing.pub"), "UNSET\n")
    File.cp!(Path.join(@repo, "scripts/install.py"), Path.join(tmp, "scripts/install.py"))
    File.write!(Path.join(tmp, "scripts/install.py"), unset_installer(tmp))
    root
  end

  defp unset_installer(tmp) do
    tmp
    |> Path.join("scripts/install.py")
    |> File.read!()
    |> String.replace(~r/^RELEASE_PUBLIC_KEY = ".*"$/m, ~s(RELEASE_PUBLIC_KEY = "UNSET"))
  end

  defp keygen(root, path, args \\ []) do
    capture_io(fn -> Release.Keygen.run(["--private-key", path | args], root) end)
  end

  defp pinned(root), do: root |> Path.join("release-signing.pub") |> File.read!() |> String.trim()

  test "the committed key file, the installer and this build pin the same key" do
    pinned = pinned(Path.join(@repo, "dist/lmx"))
    assert pinned == "UNSET" or match?({:ok, _key}, Signature.parse_public_key(pinned))
    installer = File.read!(Path.join(@repo, "scripts/install.py"))
    assert Signing.installer_key(installer) == {:ok, pinned}
    assert Signature.pinned_text() == pinned
  end

  # Owner-only is a Unix mode: Erlang reports every writable file on Windows
  # as 0666, so neither the 0600 nor `exposed?/1` means anything there.
  @tag :unix
  test "keygen writes an owner-only private key it never prints and pins the public key", %{
    tmp: tmp
  } do
    root = layout(tmp)
    before = File.read!(Path.join(tmp, "scripts/install.py"))
    path = Path.join(tmp, "keys/release.key")
    File.mkdir_p!(Path.dirname(path))

    output = keygen(root, path)

    assert %{mode: mode} = File.stat!(path)
    assert Bitwise.band(mode, 0o777) == 0o600
    refute Signing.exposed?(path)
    assert {:ok, private} = Signing.read_private_key(path)
    public = private |> Signature.public_key() |> Signature.encode_public_key()
    refute output =~ Base.encode64(private)
    assert output =~ public
    assert File.read!(Path.join(root, "release-signing.pub")) == public <> "\n"

    installer = File.read!(Path.join(tmp, "scripts/install.py"))
    assert Signing.installer_key(installer) == {:ok, public}
    assert String.replace(installer, public, "UNSET") == before

    assert Path.wildcard(Path.join(Path.dirname(path), ".lmx-release-key-*"), match_dot: true) ==
             []

    # Never overwritten, and a pinned key changes only with --rotate.
    contents = File.read!(path)
    assert_raise Mix.Error, ~r/already exists/, fn -> keygen(root, path) end
    assert File.read!(path) == contents
    other = Path.join(tmp, "keys/next.key")
    assert_raise Mix.Error, ~r/already pins a release-signing key/, fn -> keygen(root, other) end
    refute File.exists?(other)
    keygen(root, other, ["--rotate"])
    {:ok, rotated} = Signing.read_private_key(other)
    assert pinned(root) == rotated |> Signature.public_key() |> Signature.encode_public_key()
    refute pinned(root) == public
  end

  test "sign and verify cover the pinned key only and report every bad file", %{tmp: tmp} do
    root = layout(tmp)
    key = Path.join(tmp, "release.key")
    keygen(root, key)
    files = for name <- ["SHA256SUMS", "update.json"], do: Path.join(tmp, name)
    Enum.each(files, &File.write!(&1, "contents of #{Path.basename(&1)}\n"))

    output = capture_io(fn -> Release.Sign.run(["--private-key", key | files], root) end)
    assert output =~ "SHA256SUMS.sig"
    {:ok, {:ok, public}} = Signing.read_pinned(Path.join(root, "release-signing.pub"))

    for file <- files do
      signature = File.read!(file <> ".sig")
      assert byte_size(signature) == 89 and String.ends_with?(signature, "==\n")
      assert :ok = Signature.verify(File.read!(file), signature, public)
    end

    assert capture_io(fn -> Release.Verify.run(files, root) end) =~ "Verified"

    # Another key's signatures would be rejected by every build: refuse them.
    stranger = Path.join(tmp, "stranger.key")
    keygen(layout(Path.join(tmp, "stranger")), stranger)

    assert_raise Mix.Error, ~r/does not belong to the pinned public key/, fn ->
      capture_io(fn -> Release.Sign.run(["--private-key", stranger, hd(files)], root) end)
    end

    File.write!(hd(files), "changed after signing\n")
    File.rm!(List.last(files) <> ".sig")

    error =
      assert_raise Mix.Error, fn -> capture_io(fn -> Release.Verify.run(files, root) end) end

    assert error.message =~ "SHA256SUMS: the signature does not verify"
    assert error.message =~ "update.json.sig: cannot read it"

    unset = layout(Path.join(tmp, "unset"))

    assert_raise Mix.Error, ~r/no key is pinned yet/, fn ->
      Release.Verify.run(files, unset)
    end

    # With nothing pinned, no build could check a signature: refuse to make one.
    assert_raise Mix.Error, ~r/release-signing.pub is UNSET\); run mix lmx.release.keygen/, fn ->
      capture_io(fn -> Release.Sign.run(["--private-key", key, hd(files)], unset) end)
    end
  end

  test "keys inside a Git checkout are refused, for writing and for signing", %{tmp: tmp} do
    root = layout(tmp)

    # A checkout's .git is a directory; a worktree's is a file.
    for {name, make_git} <- [
          {"checkout", &File.mkdir_p!/1},
          {"worktree", &File.write!(&1, "gitdir: x\n")}
        ] do
      top = Path.join(tmp, name)
      File.mkdir_p!(Path.join(top, "dist/lmx"))
      make_git.(Path.join(top, ".git"))
      inside = Path.join(top, "dist/lmx/release.key")

      error = assert_raise Mix.Error, fn -> keygen(root, inside) end
      assert error.message =~ "inside the Git checkout #{Path.expand(top)}"
      refute File.exists?(inside)
      assert Path.wildcard(Path.join(top, "dist/lmx/.lmx-release-key-*"), match_dot: true) == []
      assert pinned(root) == "UNSET"
    end

    # A key moved into a checkout afterwards is refused when signing, too.
    key = Path.join(tmp, "release.key")
    keygen(root, key)
    moved = Path.join(tmp, "checkout/dist/lmx/release.key")
    File.cp!(key, moved)
    File.chmod!(moved, 0o600)
    file = Path.join(tmp, "SHA256SUMS")
    File.write!(file, "sums\n")

    assert_raise Mix.Error, ~r/inside the Git checkout/, fn ->
      capture_io(fn -> Release.Sign.run(["--private-key", moved, file], root) end)
    end

    refute File.exists?(file <> ".sig")

    assert_raise Mix.Error, ~r/inside the Git checkout/, fn ->
      Release.SignDraft.run(["--tag", "v1.2.3", "--private-key", moved],
        root: root,
        runner: fn _args -> flunk("must not run gh") end
      )
    end
  end

  # A stand-in for `gh`: the draft's assets are files in `assets`, and every
  # command is reported to the test.
  defp gh(assets, state \\ []) do
    owner = self()

    state =
      Map.merge(
        %{"isDraft" => true, "isPrerelease" => false},
        Map.new(state, fn {field, value} -> {Atom.to_string(field), value} end)
      )

    fn args ->
      send(owner, {:gh, args})
      gh_command(args, assets, state)
    end
  end

  defp gh_command(
         ["release", "view", "v1.2.3", "--repo", "houllette/lemieux", "--json", fields],
         _assets,
         state
       ) do
    assert fields == "isDraft,isPrerelease"
    {JSON.encode!(state) <> "\n", 0}
  end

  defp gh_command(
         [
           "release",
           "download",
           "v1.2.3",
           "--repo",
           "houllette/lemieux",
           "--dir",
           dir | patterns
         ],
         assets,
         _state
       ) do
    for ["--pattern", name] <- Enum.chunk_every(patterns, 2),
        File.exists?(Path.join(assets, name)),
        do: File.cp!(Path.join(assets, name), Path.join(dir, name))

    {"", 0}
  end

  defp gh_command(["release", "upload", "v1.2.3" | rest], assets, _state) do
    {files, ["--clobber", "--repo", "houllette/lemieux"]} = Enum.split(rest, -3)
    Enum.each(files, &File.cp!(&1, Path.join(assets, Path.basename(&1))))
    {"", 0}
  end

  defp gh_command(_other, _assets, _state), do: {"unexpected gh command", 1}

  defp gh_commands do
    receive do
      {:gh, [_release, command | _]} -> [command | gh_commands()]
    after
      0 -> []
    end
  end

  defp sha256(text), do: Base.encode16(:crypto.hash(:sha256, text), case: :lower)

  # An entry Lmx.Update.select/2 accepts.
  defp entry(version, target, sha256) do
    digest = String.duplicate("d", 64)

    %{
      "version" => version,
      "target" => target,
      "sha256" => sha256,
      "build_id" => digest,
      "native_id" => digest,
      "dependency_id" => digest,
      "config_id" => digest,
      "erts" => "17.0.2",
      "elixir" => "1.20.2",
      "dependencies" => %{},
      "hot_modules" => [],
      "upgrade_from" => []
    }
  end

  # A draft's assets as release CI uploads them. `:targets` and `:archives`
  # edit what update.json and SHA256SUMS say about the archives.
  defp draft(tmp, root, opts \\ []) do
    version = Keyword.get(opts, :version, "1.2.3")
    assets = Path.join(tmp, "assets")
    File.mkdir_p!(assets)
    archives = Map.new(~w(linux macos), &{&1, sha256("archive for " <> &1)})

    targets =
      Map.new(archives, fn {target, digest} -> {target, entry(version, target, digest)} end)

    targets = Keyword.get(opts, :targets, & &1).(targets)
    manifest = %{"schema_version" => 1, "version" => version, "targets" => targets}
    File.write!(Path.join(assets, "update.json"), JSON.encode!(manifest))
    File.cp!(Path.expand("../../scripts/install.py", root), Path.join(assets, "install.py"))

    listed =
      for {target, digest} <- Keyword.get(opts, :archives, & &1).(archives),
          do: "#{digest}  lmx_#{target}.tar.gz\n"

    signed =
      for name <- ["update.json", "install.py"],
          do: sha256(File.read!(Path.join(assets, name))) <> "  " <> name <> "\n"

    File.write!(Path.join(assets, "SHA256SUMS"), listed ++ signed)
    assets
  end

  test "sign_draft signs a draft through gh, verifies the upload and never publishes", %{
    tmp: tmp
  } do
    root = layout(tmp)
    key = Path.join(tmp, "release.key")
    keygen(root, key)
    assets = draft(tmp, root)
    args = ["--tag", "v1.2.3", "--private-key", key]

    output = capture_io(fn -> Release.SignDraft.run(args, root: root, runner: gh(assets)) end)

    assert output =~ "still unpublished"
    refute output =~ "pre-release"
    assert gh_commands() == ["view", "download", "upload", "download"]
    {:ok, {:ok, public}} = Signing.read_pinned(Path.join(root, "release-signing.pub"))

    for name <- ["SHA256SUMS", "update.json"] do
      assets
      |> Path.join(name)
      |> File.read!()
      |> Signature.verify(File.read!(Path.join(assets, name <> ".sig")), public)
      |> then(&assert(&1 == :ok))
    end

    # releases/latest skips pre-releases, so publishing one as it is would
    # reach no installer and no installed lmx.
    output =
      capture_io(fn ->
        Release.SignDraft.run(args, root: root, runner: gh(assets, isPrerelease: true))
      end)

    assert output =~ "v1.2.3 is marked as a pre-release"
    assert output =~ "clear \"Set as a pre-release\""
  end

  test "sign_draft refuses published releases, mismatched drafts and foreign keys before uploading",
       %{tmp: tmp} do
    root = layout(tmp)
    key = Path.join(tmp, "release.key")
    keygen(root, key)
    args = ["--tag", "v1.2.3", "--private-key", key]
    assets = draft(tmp, root)

    for state <- [[isDraft: false], [isDraft: nil]] do
      assert_raise Mix.Error, ~r/not a draft release|did not report whether/, fn ->
        Release.SignDraft.run(args, root: root, runner: gh(assets, state))
      end

      assert gh_commands() == ["view"]
    end

    # A draft built before the key was pinned ships an installer that refuses
    # every network install; signing it would publish that.
    unpinned = layout(Path.join(tmp, "unpinned"))
    early = draft(Path.join(tmp, "unpinned"), unpinned)

    # install.py trusts SHA256SUMS and installed lmx trusts update.json: an
    # archive swapped in one of them alone, an archive only one of them
    # names, or an entry the updater would reject is never signed.
    swapped = &Map.put(&1, "linux", sha256("another archive"))
    extra = &Map.put(&1, "windows", sha256("archive for windows"))
    broken = &Map.update!(&1, "linux", fn entry -> Map.delete(entry, "config_id") end)

    for {name, opts, message} <- [
          {"swapped", [archives: swapped], ~r/give lmx_linux.tar.gz different digests/},
          {"extra", [archives: extra], ~r/list different archives/},
          {"broken", [targets: broken], ~r/entry for linux would be rejected by lmx's updater/},
          {"empty", [targets: fn _ -> %{} end, archives: fn _ -> %{} end], ~r/lists no archives/},
          {"stale", [version: "1.2.2"], ~r/does not name version 1.2.3/}
        ] do
      mismatched = draft(Path.join(tmp, name), root, opts)

      assert_raise Mix.Error, message, fn ->
        Release.SignDraft.run(args, root: root, runner: gh(mismatched))
      end

      assert gh_commands() == ["view", "download"]
      assert Path.wildcard(Path.join(mismatched, "*.sig")) == []
    end

    assert_raise Mix.Error, ~r/pins UNSET, not the key in release-signing.pub/, fn ->
      Release.SignDraft.run(args, root: root, runner: gh(early))
    end

    assert gh_commands() == ["view", "download"]
    assert Path.wildcard(Path.join(early, "*.sig")) == []
    stranger = Path.join(tmp, "stranger.key")
    keygen(layout(Path.join(tmp, "stranger")), stranger)

    assert_raise Mix.Error, ~r/does not belong to the pinned public key/, fn ->
      Release.SignDraft.run(["--tag", "v1.2.3", "--private-key", stranger],
        root: root,
        runner: gh(assets)
      )
    end

    assert_raise Mix.Error, ~r/stable release/, fn ->
      Release.SignDraft.run(["--tag", "1.2.3", "--private-key", key],
        root: root,
        runner: gh(assets)
      )
    end

    assert gh_commands() == []
    assert Path.wildcard(Path.join(assets, "*.sig")) == []
    assert_raise Mix.Error, ~r/usage/, fn -> Release.SignDraft.run(["--tag", "v1.2.3"], []) end
  end
end

defmodule Lmx.ReleaseSigningEnvTest do
  # Application env is global, so this module runs alone.
  use ExUnit.Case, async: false

  alias Lmx.Update.Signature

  test "tests and hosts can inject the verification key through application env" do
    {public, private} = :crypto.generate_key(:eddsa, :ed25519)
    # 10.2.0: above any real version, so the manifest is always newer than lmx.
    target = Lmx.Release.target()

    info = %{
      "version" => "10.2.0",
      "target" => target,
      "erts" => "17.0.2",
      "elixir" => "1.20.2",
      "dependencies" => %{},
      "hot_modules" => [],
      "upgrade_from" => []
    }

    info =
      Enum.reduce(~w(sha256 build_id native_id dependency_id config_id), info, fn key, info ->
        Map.put(info, key, String.duplicate("c", 64))
      end)

    body =
      JSON.encode!(%{
        "schema_version" => 1,
        "version" => "10.2.0",
        "targets" => %{target => info}
      })

    routes = %{
      "https://github.com/houllette/lemieux/releases/latest/download/update.json" => body,
      "https://github.com/houllette/lemieux/releases/download/v10.2.0/update.json.sig" =>
        Signature.sign(body, private)
    }

    get = fn url, opts ->
      {:cont, {_, response}} =
        opts[:into].({:data, routes[url]}, {%Req.Request{}, %Req.Response{status: 200}})

      {:ok, response}
    end

    Application.put_env(:lmx, :release_public_key, Base.encode64(public))
    on_exit(fn -> Application.delete_env(:lmx, :release_public_key) end)
    assert {:ok, %{"version" => "10.2.0"}} = Lmx.Update.check(get: get)
    Application.put_env(:lmx, :release_public_key, "UNSET")
    assert {:unverified, "10.2.0", :signing_key_unset} = Lmx.Update.check(get: get)
  end
end
